    if (compressed_data == NULL || output_buffer == NULL || compressed_len < 0 || output_size < 0) {
        return -1;
    }

    int input_index = 0;
    int output_index = 0;

    while (1) {
        /* Step 2: Check if we have enough input bytes to read a full unit, or if output is full */
        if (compressed_len - input_index < 2 || output_index >= output_size) {
            break;
        }

        /* Step 3: Read count and value */
        unsigned char count = compressed_data[input_index];
        unsigned char value = compressed_data[input_index + 1];

        /* Step 4: Advance input pointer */
        input_index += 2;

        /* Validate count: 0 is reserved and unused */
        if (count == 0) {
            return -1; 
        }

        /* Step 5: Write 'value' repeatedly into output_buffer for 'count' times */
        for (int i = 0; i < count; i++) {
            /* Check output_index < output_size before each write */
            if (output_index >= output_size) {
                return -1; /* Output buffer overflow */
            }
            output_buffer[output_index++] = value;
        }
    }

    /* Step 7: If stopped due to insufficient output_size while input_index < compressed_len - 1, 
       treat as failure. A single trailing byte is ignored. */
    if (input_index < compressed_len - 1) {
        return -1;
    }

    /* Return the length of the decompressed data */
    return output_index;
}
